export const bins=[[-Infinity,-600,'< −10 min'],[-600,-300,'−10 to −5'],[-300,-120,'−5 to −2'],[-120,0,'−2 to 0'],[0,120,'0 to +2'],[120,300,'+2 to +5'],[300,600,'+5 to +10'],[600,Infinity,'≥ +10 min']];
export function summarize(rows){const delays=[],days=new Map(),counts=Array(8).fill(0);let flagged=0;for(const row of rows){const {date,v}=row;if(v[5])flagged++;if(v[4]===null||!Number.isFinite(v[4]))continue;const delay=v[4];delays.push(delay);const day=days.get(date)||{date,n:0,within:0};day.n++;day.within+=Math.abs(delay)<=120;days.set(date,day);let index=delay===120?4:bins.findIndex(([lo,hi])=>delay>=lo&&delay<hi);if(index<0)index=7;counts[index]++}delays.sort((a,b)=>a-b);const n=delays.length;return {records:rows.length,valid:n,flagged,median:n?(delays[Math.floor((n-1)/2)]+delays[Math.ceil((n-1)/2)])/2:null,within:n?delays.filter(v=>Math.abs(v)<=120).length/n:null,days:[...days.values()].sort((a,b)=>a.date.localeCompare(b.date)),counts}}
export function filterRows(rows,{stop='',dest='',exclude=false}){return rows.filter(({v})=>(stop===''||v[1]===Number(stop))&&(dest===''||v[2]===Number(dest))&&(!exclude||v[5]===0))}
export function sortRows(rows,sort){const chronological=(a,b)=>a.date.localeCompare(b.date)||a.v[3]-b.v[3]||a.v[0].localeCompare(b.v[0]);return [...rows].sort((a,b)=>sort==='late'||sort==='early'?(a.v[4]===null?1:b.v[4]===null?-1:(sort==='late'?b.v[4]-a.v[4]:a.v[4]-b.v[4]))||chronological(a,b):sort==='oldest'?chronological(a,b):chronological(b,a))}
export function civilTime(date,seconds){const [y,m,d]=date.split('-').map(Number);return new Date(Date.UTC(y,m-1,d,0,0,seconds)).toISOString().slice(0,19).replace('T',' ')}
